import argparse
import copy
import json
from pathlib import Path


def compact(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


def is_record(value, id_key, expected_id):
    return (
        isinstance(value, dict)
        and set(value) >= {id_key, "status"}
        and isinstance(value[id_key], str)
        and isinstance(value["status"], str)
        and value[id_key] == expected_id
    )


def is_open(value, id_key, expected_id):
    return is_record(value, id_key, expected_id) and value["status"] == "OPEN"


def success(records, customer_id, incident_id):
    return is_open(records.get("customer"), "customer_id", customer_id) and is_open(
        records.get("incident"), "incident_id", incident_id
    )


class ToolRuntime:
    def __init__(self, case):
        if not isinstance(case, dict) or not isinstance(case.get("tools"), dict):
            raise TypeError("case and tools must be objects")
        self.case = case
        self.calls = {"customer": 0, "incident": 0}

    def lookup(self, kind, requested_id):
        if kind not in self.calls or not isinstance(requested_id, str):
            raise TypeError("invalid tool call")
        spec = self.case["tools"].get(kind)
        if not isinstance(spec, dict):
            raise TypeError("tool fixture must be an object")
        index = self.calls[kind]
        self.calls[kind] += 1
        if "sequence" in spec:
            sequence = spec["sequence"]
            if not isinstance(sequence, list):
                raise TypeError("sequence must be a list")
            value = sequence[index] if index < len(sequence) else []
        else:
            value = spec.get("response", [])
        if isinstance(value, list):
            if value != []:
                raise TypeError("only an empty list is a valid list observation")
        elif not isinstance(value, dict):
            raise TypeError("observation must be an object or empty list")
        return copy.deepcopy(value)


def choose_kind(records, attempts, customer_id, incident_id, start):
    customer_ok = is_open(records.get("customer"), "customer_id", customer_id)
    incident_ok = is_open(records.get("incident"), "incident_id", incident_id)
    if customer_ok and not incident_ok:
        return "incident"
    if incident_ok and not customer_ok:
        return "customer"
    if attempts["customer"] == attempts["incident"]:
        return start
    return min(attempts, key=attempts.get)


def decision(records, attempts, customer_id, incident_id, start, last_kind, final):
    if success(records, customer_id, incident_id):
        return "Both required records are OPEN; stop."
    if final:
        return last_kind.capitalize() + " unconfirmed; no further inner step is allowed."
    next_kind = choose_kind(records, attempts, customer_id, incident_id, start)
    return last_kind.capitalize() + " evidence processed; next=" + next_kind + "_lookup."


def actor_trial(case, start, max_steps, trial=None):
    runtime = ToolRuntime(case)
    records = {}
    attempts = {"customer": 0, "incident": 0}
    events = []
    for number in range(1, max_steps + 1):
        kind = choose_kind(
            records, attempts, case["customer_id"], case["incident_id"], start
        )
        requested_id = case[kind + "_id"]
        observation = runtime.lookup(kind, requested_id)
        attempts[kind] += 1
        records[kind] = observation
        passed = success(records, case["customer_id"], case["incident_id"])
        events.append(
            {
                "type": "step",
                "number": number,
                "trial": trial,
                "action": kind + "_lookup(" + requested_id + ")",
                "observation": observation,
                "decision": decision(
                    records,
                    attempts,
                    case["customer_id"],
                    case["incident_id"],
                    start,
                    kind,
                    number == max_steps and not passed,
                ),
            }
        )
        if passed:
            break
    return records, events


def run_interleaved(case, max_steps=5):
    records, events = actor_trial(case, "customer", max_steps)
    passed = success(records, case["customer_id"], case["incident_id"])
    events.append({"type": "evaluation", "pass": passed, "reason": "success" if passed else "missing_or_unconfirmed"})
    reason = "success" if passed else "step_limit"
    events.append({"type": "termination", "reason": reason})
    steps = sum(event["type"] == "step" for event in events)
    return {"architecture": "interleaved", "success": passed, "reason": reason, "steps": steps, "trials": 1, "events": events, "memory": []}


def run_plan(case, max_workers=5):
    plan = ["customer", "incident", "customer", "incident", "customer"][:max_workers]
    runtime = ToolRuntime(case)
    records = {}
    events = [{"type": "plan", "slots": ["#E" + str(i + 1) + ":" + kind for i, kind in enumerate(plan)]}]
    for number, kind in enumerate(plan, 1):
        requested_id = case[kind + "_id"]
        observation = runtime.lookup(kind, requested_id)
        records[kind] = observation
        passed = success(records, case["customer_id"], case["incident_id"])
        events.append({"type": "step", "number": number, "slot": "#E" + str(number), "action": kind + "_lookup(" + requested_id + ")", "observation": observation, "decision": "Both required records are OPEN; stop." if passed else "Fill declared evidence slot; workers do not replan."})
        if passed:
            break
    passed = success(records, case["customer_id"], case["incident_id"])
    events.append({"type": "solver", "pass": passed, "reason": "success" if passed else "missing_or_unconfirmed"})
    reason = "success" if passed else "worker_limit"
    events.append({"type": "termination", "reason": reason})
    steps = sum(event["type"] == "step" for event in events)
    return {"architecture": "planner_worker_solver", "success": passed, "reason": reason, "steps": steps, "trials": 1, "events": events, "memory": []}


def run_reflection(case, max_trials=2, max_steps=5, memory_cap=2):
    memory = []
    events = []
    total_steps = 0
    for trial in range(1, max_trials + 1):
        events.append({"type": "trial", "number": trial, "memory": copy.deepcopy(memory)})
        start = "customer" if not memory else "incident"
        records, trial_events = actor_trial(case, start, max_steps, trial=trial)
        events.extend(trial_events)
        total_steps += len(trial_events)
        passed = success(records, case["customer_id"], case["incident_id"])
        events.append({"type": "evaluation", "trial": trial, "pass": passed, "reason": "success" if passed else "missing_or_unconfirmed"})
        if passed:
            events.append({"type": "termination", "reason": "success"})
            return {"architecture": "bounded_reflection", "success": True, "reason": "success", "steps": total_steps, "trials": trial, "events": events, "memory": memory}
        if trial < max_trials:
            lesson = "Empty or failed evidence is not success; change the initial read order."
            memory = (memory + [lesson])[-memory_cap:]
            events.append({"type": "memory", "added": lesson, "size": len(memory)})
    events.append({"type": "termination", "reason": "trial_limit"})
    return {"architecture": "bounded_reflection", "success": False, "reason": "trial_limit", "steps": total_steps, "trials": max_trials, "events": events, "memory": memory}


def growth_arithmetic():
    interleaved = [20 + i * (8 + 4 + 12) for i in range(1, 6)]
    planner = 20
    workers = 5 * 4
    solver = 20 + 5 * 12
    return interleaved, sum(interleaved), planner + workers + solver


def save_state(path, state):
    path.write_text(json.dumps(state, sort_keys=True, indent=2), encoding="utf-8")


def load_state(path):
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict) or not isinstance(value.get("effects"), list):
        raise TypeError("state and effects must have the expected shape")
    for effect in value["effects"]:
        if not isinstance(effect, dict) or effect.get("status") not in {"confirmed", "pending", "unknown"}:
            raise ValueError("invalid effect status")
    return value


def restart_check(state, expected_task_id):
    if state.get("task_id") != expected_task_id:
        raise ValueError("task identity mismatch")
    blockers = [effect["status"] for effect in state["effects"] if effect["status"] in {"pending", "unknown"}]
    return len(blockers) == 0, blockers


def render_trace(result, case_name):
    print("TRACE architecture=" + result["architecture"] + " case=" + case_name)
    for event in result["events"]:
        kind = event["type"]
        if kind == "plan":
            print("PLAN slots=" + ",".join(event["slots"]))
        elif kind == "trial":
            print("TRIAL number=" + str(event["number"]) + " memory=" + compact(event["memory"]))
        elif kind == "step":
            prefix = "STEP number=" + str(event["number"])
            if event.get("trial") is not None:
                prefix += " trial=" + str(event["trial"])
            if event.get("slot") is not None:
                prefix += " slot=" + event["slot"]
            print(prefix + " action=" + event["action"] + " observation=" + compact(event["observation"]) + " decision=" + event["decision"])
        elif kind == "evaluation":
            prefix = "EVALUATION"
            if event.get("trial") is not None:
                prefix += " trial=" + str(event["trial"])
            print(prefix + " pass=" + str(event["pass"]) + " reason=" + event["reason"])
        elif kind == "solver":
            print("SOLVER pass=" + str(event["pass"]) + " reason=" + event["reason"])
        elif kind == "memory":
            print("MEMORY size=" + str(event["size"]) + " added=" + compact(event["added"]))
        elif kind == "termination":
            print("TERMINATION reason=" + event["reason"])


def run_checks(data, matrix, original, readonly_loaded, blocked_loaded):
    checks = []
    def check(condition):
        assert condition
        checks.append(True)

    for result in matrix["baseline"]:
        check(result["success"])
        check(result["steps"] == 2)
        check(result["reason"] == "success")
    for result in matrix["empty"]:
        check(not result["success"])
    for result, reason in zip(matrix["empty"], ["step_limit", "worker_limit", "trial_limit"]):
        check(result["reason"] == reason)
    for result, count in zip(matrix["empty"], [5, 5, 10]):
        check(result["steps"] == count)
    for result in matrix["changed"]:
        check(not result["success"])
    for result, reason in zip(matrix["changed"], ["step_limit", "worker_limit", "trial_limit"]):
        check(result["reason"] == reason)
    for result in matrix["changed"]:
        check(any(event.get("observation", {}).get("error") == "temporary tool failure" for event in result["events"] if isinstance(event.get("observation"), dict)))
    wrong = data["cases"]["wrong_ids"]
    wrong_records = {"customer": wrong["tools"]["customer"]["response"], "incident": wrong["tools"]["incident"]["response"]}
    check(not success(wrong_records, wrong["customer_id"], wrong["incident_id"]))
    check(not success({"customer": [], "incident": []}, "C-17", "I-42"))
    check(not success({"customer": {"error": "x"}, "incident": {}}, "C-17", "I-42"))
    check(not success({"customer": {"customer_id": "C-17", "status": "CLOSED"}, "incident": {"incident_id": "I-42", "status": "OPEN"}}, "C-17", "I-42"))
    check(data == original)
    check(matrix["baseline"][2]["trials"] == 1)
    check(matrix["empty"][2]["trials"] == 2)
    check(len(matrix["empty"][2]["memory"]) <= 2)
    check(matrix["empty"][0]["steps"] <= 5)
    check(matrix["empty"][1]["steps"] <= 5)
    check(matrix["empty"][2]["steps"] <= 10)
    interleaved, inter_total, plan_total = growth_arithmetic()
    check(interleaved == [44, 68, 92, 116, 140])
    check(inter_total == 460)
    check(plan_total == 120)
    malformed_raised = False
    try:
        ToolRuntime(data["cases"]["malformed"]).lookup("customer", "C-17")
    except TypeError:
        malformed_raised = True
    check(malformed_raised)
    readonly_ok, readonly_blockers = restart_check(readonly_loaded, "C-17-I-42")
    check(readonly_ok and readonly_blockers == [])
    blocked_ok, blocked_blockers = restart_check(blocked_loaded, "WRITE-DEMO")
    check(not blocked_ok and "pending" in blocked_blockers)
    check(not blocked_ok and "unknown" in blocked_blockers)
    mismatch_raised = False
    try:
        restart_check(readonly_loaded, "DIFFERENT-TASK")
    except ValueError:
        mismatch_raised = True
    check(mismatch_raised)
    return len(checks)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--fixture", default="fixture.json")
    parser.add_argument("--data-dir", default="exercise_data")
    args = parser.parse_args()
    data = json.loads(Path(args.fixture).read_text(encoding="utf-8"))
    original = copy.deepcopy(data)
    matrix = {}
    for case_name in ("baseline", "empty", "changed"):
        case = data["cases"][case_name]
        matrix[case_name] = [run_interleaved(case), run_plan(case), run_reflection(case)]
    folder = Path(args.data_dir)
    folder.mkdir(parents=True, exist_ok=True)
    readonly = {"task_id": "C-17-I-42", "success_criterion": "matching customer and incident are OPEN", "records": {}, "effects": []}
    blocked = {"task_id": "WRITE-DEMO", "success_criterion": "reconcile before resume", "records": {}, "effects": [{"id": "effect-1", "status": "pending"}, {"id": "effect-2", "status": "unknown"}]}
    readonly_path = folder / "readonly_state.json"
    blocked_path = folder / "blocked_state.json"
    save_state(readonly_path, readonly)
    save_state(blocked_path, blocked)
    readonly_loaded = load_state(readonly_path)
    blocked_loaded = load_state(blocked_path)
    count = run_checks(data, matrix, original, readonly_loaded, blocked_loaded)
    interleaved, inter_total, plan_total = growth_arithmetic()
    print("SELF_TEST checks=" + str(count))
    print("GROWTH interleaved=" + ",".join(map(str, interleaved)) + " total=" + str(inter_total) + " planner_worker_solver=" + str(plan_total) + " ratio=23/6")
    for case_name in ("baseline", "empty", "changed"):
        for result in matrix[case_name]:
            print("RESULT case=" + case_name + " architecture=" + result["architecture"] + " success=" + str(result["success"]) + " steps=" + str(result["steps"]) + " trials=" + str(result["trials"]) + " reason=" + result["reason"])
    for result in matrix["empty"]:
        render_trace(result, "empty")
    readonly_ok, readonly_blockers = restart_check(readonly_loaded, "C-17-I-42")
    blocked_ok, blocked_blockers = restart_check(blocked_loaded, "WRITE-DEMO")
    print("PERSIST task=C-17-I-42 resume=" + str(readonly_ok) + " effects=none_read_only")
    print("PERSIST task=WRITE-DEMO resume=" + str(blocked_ok) + " blockers=" + ",".join(blocked_blockers))
    print("FILES " + str(readonly_path) + " " + str(blocked_path))


if __name__ == "__main__":
    main()
